describe('Dropdown Menu Navigation with Keyboard Arrow Keys', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('.dropdown-toggle').click(); // Open the dropdown menu
    });

    it('should navigate to the next item using the down arrow key', () => {
        cy.get('.dropdown-item').first().focus(); // Focus on the first item
        cy.get('body').type('{downarrow}'); // Press down arrow key
        cy.get('.dropdown-item').eq(1).should('have.class', 'focused'); // Check if the second item is focused
    });

    it('should wrap around to the last item using the down arrow key from the last item', () => {
        cy.get('.dropdown-item').last().focus(); // Focus on the last item
        cy.get('body').type('{downarrow}'); // Press down arrow key
        cy.get('.dropdown-item').first().should('have.class', 'focused'); // Check if the first item is focused
    });
});
